def execute(self) -> int | None:
    state.set("_ProcessParallel")
    self._logger.info(
        "Multi process start. Execute step count=%s." % self._config.multi_process_count
    )
    install_mp_handler()
    packed = [cloudpickle.dumps(step) for step in self._steps]

    try:
        with Pool(processes=self._config.multi_process_count) as p:
            for r in p.imap_unordered(self._async_step_execute, packed):
                if r == "NG":
                    if self._config.force_continue:
                        self._logger.warning("Multi process response. %s" % r)
                    else:
                        raise StepExecutionFailed("Multi process response. %s" % r)
    except Exception:
        self._logger.exception("Exception occurred during multi process execution.")
        return StepStatus.ABNORMAL_TERMINATION

def execute(self, *args):
    files = self.get_src_files()
    if not self.check_file_existence(files):
        self.logger.info("No files are found. Nothing to do.")
        return

    key_file = self._resolve("adapter_file", File).get_target_files(
        self.args.key_dir, self.args.key_pattern
    )
    if len(key_file) != 1:
        self.logger.info("Key file must be only one.")
        return

    with open("".join(key_file), "r") as k:
        key = k.read()

    for file in files:
        dest_path = os.path.join(self.args.resolve_dest_dir(), os.path.basename(file))
        self._process(file, dest_path, key)

def execute(self, *args):
    # Setting Up Directory
    default_dir = os.getcwd()

    try:
        if self.args.work_dir:
            os.chdir(self.args.work_dir)

        if isinstance(self.args.command, str):
            content = self.args.command
        else:
            content = self.args.command.content

        if content:
            for command in content.split("&&"):
                subprocess.run(command.strip().split(" "))
        elif self.args.command.file:
            subprocess.call(self.args.command.file)
    finally:
        # Set Directory to default
        if self.args.work_dir:
            os.chdir(default_dir)
